"""Own controller enforcing overhead alignment before button descent."""
from pathlib import Path
import json
import numpy as np
import mw_tool

def candidate(s,p,trace=False):
    s.reset()
    xy=s.obs[4:6].copy()
    safe_z=p.get('safe_z',.4)
    overhead=np.r_[xy,safe_z]
    logs=[]
    def step(a):
        q=s.step(a)
        if trace:logs.append([len(s.actions),*s.env.tcp_center,*s.data.mocap_pos[0],s.obs[6],q['obj_to_target'],s.data.qvel[9]])
        return q
    for _ in range(100):
        err=overhead-s.data.mocap_pos[0]
        if np.max(abs(err))<1e-10:break
        step(np.r_[np.clip(err/.01,-1,1),1])
    for _ in range(80):
        if np.linalg.norm(xy-s.env.tcp_center[:2])<=p.get('alignment_tolerance',.005):break
        step(np.r_[np.clip(p.get('gain_xy',20)*(xy-s.env.tcp_center[:2]),-p.get('speed_xy',.7),p.get('speed_xy',.7)),0,1])
    alignment={'tcp':s.env.tcp_center.tolist(),'mocap':s.data.mocap_pos[0].tolist(),'obj_distance':s.check()['obj_to_target'],'step':len(s.actions)}
    for _ in range(p.get('press_steps',70)):
        if p.get('mode','tcp')=='button':
            error=s.obs[6]-s.target_pos[2]-p.get('button_gap',.003)
            if error<=p.get('deadband',.0005):break
            az=-np.clip(p.get('gain_z',100)*error,p.get('min_speed',.1),p.get('speed_z',1.))
        else:
            az=np.clip(p.get('gain_z',35)*(p.get('tcp_z',.18)-s.env.tcp_center[2]),-p.get('speed_z',1),p.get('speed_z',1))
        axy=np.clip(p.get('gain_xy',20)*(xy-s.env.tcp_center[:2]),-p.get('speed_xy',.7),p.get('speed_xy',.7))
        step(np.r_[axy,az,1])
    for _ in range(p.get('hold_steps',40)):step([0,0,0,1])
    q=s.check()
    q.update(params=p,alignment=alignment,tcp=s.env.tcp_center.tolist(),mocap=s.data.mocap_pos[0].tolist(),grip=float(s.obs[3]),button_velocity=float(s.data.qvel[9]))
    return q,np.asarray(s.actions),logs

if __name__=='__main__':
    s=mw_tool.Session('/app/instance.npz')
    results=[]
    best=None
    for safe_z in [.38,.4,.42]:
     for alignment_tolerance in [.003,.006,.012]:
      for press_steps in [35,50,65]:
       for gain_z in [20,35]:
        p={'safe_z':safe_z,'alignment_tolerance':alignment_tolerance,'press_steps':press_steps,'gain_z':gain_z,'tcp_z':.17}
        q,a,_=candidate(s,p)
        results.append(q)
        if q['success'] and q['obj_to_target']<.005 and (best is None or (q['control_steps'],q['obj_to_target'])<(best[0]['control_steps'],best[0]['obj_to_target'])):
            best=q,a
            print('BEST',json.dumps(q),flush=True)
    Path('/app/output/topdown_results.json').write_text(json.dumps(results,indent=2))
    s.save_trajectory(best[1],path='/app/output/trajectory_topdown.npz',meta=best[0])
